from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    separator = grid[0][0]

    # Full separator-color rows/columns divide the grid into independent panels.
    row_cuts = [-1] + [r for r in range(h) if all(v == separator for v in grid[r])] + [h]
    col_cuts = [-1] + [c for c in range(w) if all(grid[r][c] == separator for r in range(h))] + [w]

    for ri in range(len(row_cuts) - 1):
        r0, r1 = row_cuts[ri] + 1, row_cuts[ri + 1]
        for ci in range(len(col_cuts) - 1):
            c0, c1 = col_cuts[ci] + 1, col_cuts[ci + 1]
            if r0 >= r1 or c0 >= c1:
                continue

            # Peel off a uniform one-cell frame when present.
            cells = [(r, c) for r in range(r0, r1) for c in range(c0, c1)]
            perimeter = [(r, c) for r, c in cells
                         if r in (r0, r1 - 1) or c in (c0, c1 - 1)]
            if not perimeter:
                continue
            counts = Counter(grid[r][c] for r, c in perimeter)
            frame, frame_count = counts.most_common(1)[0]
            if frame_count == len(perimeter) and r1 - r0 > 2 and c1 - c0 > 2:
                r0, r1, c0, c1 = r0 + 1, r1 - 1, c0 + 1, c1 - 1

            height, width = r1 - r0, c1 - c0
            if height <= 0 or width <= 0:
                continue

            # Fit the simplest repeating 2-D pattern; occasional corrupt cells
            # are corrected to the most common value at their pattern position.
            best = None
            for pr in range(1, min(height, 12) + 1):
                for pc in range(1, min(width, 12) + 1):
                    groups = {}
                    for r in range(height):
                        for c in range(width):
                            groups.setdefault((r % pr, c % pc), []).append(
                                grid[r0 + r][c0 + c]
                            )
                    modes = {}
                    errors = 0
                    for key, vals in groups.items():
                        counts = Counter(vals)
                        mode = counts.most_common(1)[0][0]
                        modes[key] = mode
                        errors += len(vals) - counts[mode]
                    score = errors + 0.18 * pr * pc
                    if best is None or score < best[0]:
                        best = (score, pr, pc, modes)

            _, pr, pc, modes = best
            for r in range(height):
                for c in range(width):
                    out[r0 + r][c0 + c] = modes[(r % pr, c % pc)]

    return out
